def emit(event, **fields):
    print(json.dumps({"event": event, **fields}), flush=True)


def download(url, destination, expected, args):
    command = [
        "curl",
        "--fail",
        "--show-error",
        "--location",
        "--connect-timeout",
        "15",
        "--max-time",
        "180",
        "--retry",
        "2",
    ]
    if args.insecure:
        command += ["--insecure"]
    if args.proxy:
        command += ["--proxy", args.proxy]
    subprocess.run(command + [url, "--output", str(destination)], check=True)
    if hashlib.sha256(destination.read_bytes()).hexdigest() != expected:
        raise RuntimeError(f"Downloaded content hash mismatch: {destination}")


def run_stage(name, command, directory, environment, timeout, qfm_env=None):
    if qfm_env:
        command = [
            "bash",
            "-c",
            'source "$1" && shift && exec "$@"',
            "prolog-probe",
            str(qfm_env),
            *command,
        ]
    log = directory / f"{name}.log"
    emit("stage_begin", stage=name, log=str(log), timeout_seconds=timeout)
    with log.open("w") as stream:
        process = subprocess.Popen(
            command,
            env=environment,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            start_new_session=True,
        )

        def forward():
            for line in process.stdout:
                stream.write(line)
                stream.flush()
                print(line, end="", flush=True)

        reader = threading.Thread(target=forward, daemon=True)
        reader.start()
        try:
            code = process.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            os.killpg(process.pid, signal.SIGKILL)
            process.wait()
            reader.join(timeout=10)
            raise RuntimeError(
                f"{name} timed out; stopped only this experiment's process group; log={log}"
            ) from None
        reader.join(timeout=10)
        if reader.is_alive():
            raise RuntimeError(f"{name} output pipe did not close; inspect {log}")
    if code:
        raise RuntimeError(f"{name} failed with exit {code}; inspect {log}")
    emit("stage_complete", stage=name, passed=True, log=str(log))
    return log


